def replace_fn(src,name,new):
    start=src.index(f'function {name}')
    # next top-level function, const, or export default after start
    import re
    m=re.search(r'\n(?:function |const |export default )',src[start+10:])
    end=start+10+m.start() if m else len(src)
    return src[:start]+new+'\n'+src[end+1:]

